enum PublishStatus {
  draft('Draft'),
  published('Published'),
  archived('Archived');

  const PublishStatus(this.wire);
  final String wire;

  static PublishStatus fromJson(String value) =>
      values.firstWhere((e) => e.wire == value, orElse: () => throw FormatException('Unknown PublishStatus: $value'));

  String toJson() => wire;
}

